import {encryptMessage,decryptMessage,stats,encoder} from './crypto.mjs';
const $=id=>document.getElementById(id);let latest=null,busy=false,recoveryTimer;
const format=n=>n.toLocaleString();
function selectView(view){document.querySelectorAll('.view').forEach(el=>el.classList.toggle('hidden',el.id!==view));document.querySelectorAll('.tab').forEach(el=>{const active=el.dataset.view===view;el.classList.toggle('active',active);el.setAttribute('aria-selected',String(active));});}
document.querySelectorAll('.tab').forEach((el,i,all)=>{el.onclick=()=>selectView(el.dataset.view);el.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const next=all[(i+(e.key==='ArrowRight'?1:all.length-1))%all.length];next.focus();selectView(next.dataset.view);}};});
for(const a of document.querySelectorAll('a[href="#method"]'))a.onclick=e=>{e.preventDefault();selectView('method');};
function notify(message){$('notice').textContent=message;}
function count(){const n=encoder.encode($('message').value).length;$('count').textContent=`${format(n)} bytes / ${format([...$('message').value].length)} characters`;}
$('message').addEventListener('input',count);count();
$('sample').onclick=()=>{$('message').value='Small changes. Unpredictable outcomes. That’s the beauty of chaos.';count();notify('Example loaded. Encrypt to start a new experiment.');};
$('reveal').onclick=()=>{const shown=$('password').type==='password';$('password').type=shown?'text':'password';$('reveal').innerHTML=shown?'<svg class="visibility-icon" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m3 3 18 18M10.6 5.1A12 12 0 0 1 12 5c6.5 0 10 7 10 7a17 17 0 0 1-3 4M6.5 6.5A18 18 0 0 0 2 12s3.5 7 10 7a13 13 0 0 0 5.5-1.5M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>':'<svg class="visibility-icon" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>';const label=shown?'Hide passphrase':'Show passphrase';$('reveal').setAttribute('aria-label',label);$('reveal').title=label;$('reveal').setAttribute('aria-pressed',String(shown));};
function setBusy(value){busy=value;$('encrypt').disabled=value;for(const id of ['message','password','ciphertext'])$(id).disabled=value;$('encrypt').textContent=value?'Processing…':'Encrypt message';}
function gridLines(height){return [0,.25,.5,.75,1].map(f=>`<line x1="0" x2="720" y1="${10+f*height}" y2="${10+f*height}" stroke="#eceef1" stroke-dasharray="3 5"/>`).join('');}
function plot(result){const points=result.trajectory.map((y,i)=>`${i*720/159},${155-y*140}`).join(' ');$('chaos-chart').innerHTML=gridLines(145)+`<polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="1.5" stroke-linejoin="round"/>`;const a=stats(result.plain),b=stats(result.cipher);const max=Math.max(...b.counts,1);$('histogram').innerHTML=gridLines(200)+b.counts.map((n,i)=>`<rect x="${i*720/256}" y="${210-n/max*190}" width="2" height="${n/max*190}" fill="var(--accent)"><title>Byte ${i}: ${n} occurrences</title></rect>`).join('');$('entropy').innerHTML=`${b.entropy.toFixed(3)} <small>bits / byte</small>`;$('timing').innerHTML=`${result.elapsed.toFixed(1)} <small>ms</small>`;$('size').innerHTML=`${format(result.plain.length)} / ${format(result.cipher.length)} <small>bytes</small>`;$('sensitivity').innerHTML=`${result.sensitivity.toFixed(2)}<small>%</small>`;$('seed').textContent=result.seed.toFixed(15);$('stats-table').innerHTML=[['UTF-8 / raw bytes',a=>format(a),result.plain.length,result.cipher.length],['Shannon entropy',n=>n.toFixed(4)+' bits / byte',a.entropy,b.entropy],['Distinct byte values',format,a.unique,b.unique],['Set bits',n=>n.toFixed(2)+'%',a.ones,b.ones]].map(([label,fn,p,c])=>`<tr><td>${label}</td><td>${fn(p)}</td><td>${fn(c)}</td></tr>`).join('');renderInspection(result);}
function renderInspection(result){const rows=Array.from(result.plain.slice(0,16),(p,i)=>{const previous=i?result.cipher[i-1]:result.nonce[0];return `<tr><td>${i}</td><td>${p}</td><td>${result.bytes[i]}</td><td>${previous}</td><td>${result.cipher[i]}</td></tr>`;}).join('');let card=$('byte-inspection');if(!card){card=document.createElement('article');card.className='card comparison';card.id='byte-inspection';$('method').appendChild(card);}card.innerHTML='<h2>Inside the encryption · first 16 bytes</h2><p class="muted">Decimal values. Plaintext XOR key XOR previous ciphertext = encrypted byte.</p><table><thead><tr><th>Index</th><th>Plaintext</th><th>Key</th><th>Previous</th><th>Ciphertext</th></tr></thead><tbody>'+rows+'</tbody></table>';}
async function recoverMessage(packaged,passphrase){
  $('recovered').textContent='Verifying and decrypting…';$('recovered').classList.remove('success');$('verification').textContent='Checking authentication';$('verification').classList.remove('success');$('roundtrip').textContent='Checking';
  try{const text=await decryptMessage(packaged,passphrase);$('recovered').textContent=text;$('recovered').classList.add('success');$('verification').textContent='✓ Authentication verified';$('verification').classList.add('success');const original=latest&&packaged.trim()===latest.packaged&&text===new TextDecoder().decode(latest.plain);$('roundtrip').textContent=original?'Exact match':'Verified';$('round-note').textContent=original?'Every byte recovered successfully':'Package integrity verified';return {message:text,authenticated:true};}
  catch(e){$('recovered').textContent='Unable to decrypt this message.';$('verification').textContent='Verification failed';$('roundtrip').textContent='Failed';$('round-note').textContent='Check the passphrase and package';notify(e.message);throw e;}
}
async function runEncryption(){
  if(busy)return;clearTimeout(recoveryTimer);setBusy(true);notify('');
  try{const passphrase=$('password').value;const result=await encryptMessage($('message').value,passphrase);latest=result;$('ciphertext').value=result.packaged;$('copy').disabled=false;$('download').disabled=false;$('cipher-badge').textContent='ENCRYPTED';$('cipher-badge').classList.add('done');$('nonce-label').textContent='Nonce '+Array.from(result.nonce.slice(0,6),x=>x.toString(16).padStart(2,'0')).join('')+'…';plot(result);const recovered=await recoverMessage(result.packaged,passphrase);return {ciphertext:result.packaged,entropy:stats(result.cipher).entropy,...recovered};}
  catch(e){notify(e.message);throw e;}finally{setBusy(false);}
}
async function runDecryption(){if(busy)return;clearTimeout(recoveryTimer);setBusy(true);notify('');try{return await recoverMessage($('ciphertext').value,$('password').value);}finally{setBusy(false);}}
function scheduleRecovery(){
  clearTimeout(recoveryTimer);notify('');$('recovered').classList.remove('success');$('verification').classList.remove('success');$('roundtrip').textContent='Pending';$('round-note').textContent='Waiting for verification';
  if(!$('ciphertext').value.trim()){$('recovered').textContent='Your recovered message will appear here.';$('verification').textContent='Awaiting encryption';return;}
  $('recovered').textContent='Verifying this package…';$('verification').textContent='Awaiting verification';recoveryTimer=setTimeout(()=>runDecryption().catch(()=>{}),450);
}
$('encrypt').onclick=()=>runEncryption().catch(()=>{});
$('ciphertext').addEventListener('input',()=>{$('copy').disabled=!$('ciphertext').value;$('download').disabled=!$('ciphertext').value;$('cipher-badge').textContent=$('ciphertext').value?'EDITED':'WAITING';$('cipher-badge').classList.remove('done');scheduleRecovery();});
$('password').addEventListener('input',()=>{if($('ciphertext').value.trim())scheduleRecovery();});
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('ciphertext').value);notify('Ciphertext copied. Keep the passphrase separately.');}catch{notify('Select the ciphertext and copy it manually.');}};
$('download').onclick=()=>{const blob=new Blob([JSON.stringify({algorithm:'CHAOS-LAB-v1',ciphertext:$('ciphertext').value},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='chaos-encrypted-message.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Ciphertext downloaded. The JSON ciphertext field can be pasted back to decrypt.');};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();runEncryption().catch(()=>{});}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'encrypt_message',title:'Encrypt message',description:'Encrypt and automatically verify decryption, updating ciphertext, recovered text and statistics.',inputSchema:{type:'object',properties:{message:{type:'string'},passphrase:{type:'string'}},required:['message','passphrase'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||typeof input.message!=='string'||typeof input.passphrase!=='string'||busy)throw new Error('Provide a message and passphrase while the lab is idle.');$('message').value=input.message;$('password').value=input.passphrase;count();selectView('workspace');return runEncryption();}},{name:'decrypt_message',title:'Decrypt message',description:'Verify and decrypt a packaged ciphertext, updating the visible recovered message.',inputSchema:{type:'object',properties:{ciphertext:{type:'string'},passphrase:{type:'string'}},required:['ciphertext','passphrase'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||typeof input.ciphertext!=='string'||typeof input.passphrase!=='string'||busy)throw new Error('Provide ciphertext and a passphrase while the lab is idle.');$('ciphertext').value=input.ciphertext;$('password').value=input.passphrase;selectView('workspace');return runDecryption();}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
if(!crypto.subtle){notify('This lab requires a secure HTTPS connection for browser cryptography.');$('encrypt').disabled=true;}
